param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant()
if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Boxed value membership reference requires pinned CoreLib.'}
$samples=@(@{name='null';value=($null)},@{name='object';value=([object]::new())},@{name='string';value=('text')},@{name='boolFalse';value=($false)},@{name='boolTrue';value=($true)},@{name='char';value=([char]65)},@{name='sbyte';value=([sbyte]-1)},@{name='byte';value=([byte]255)},@{name='short';value=([short]-2)},@{name='ushort';value=([ushort]65535)},@{name='int';value=([int]-3)},@{name='uint';value=([uint]4294967295)},@{name='long';value=([long]-4)},@{name='ulong';value=([ulong]::MaxValue)},@{name='single';value=([single]1.25)},@{name='double';value=([double]1.25)},@{name='decimal';value=([decimal]1.5)},@{name='datetime';value=([DateTime]::new([long]1,[DateTimeKind]::Utc))},@{name='timespan';value=([TimeSpan]::new([long]1))},@{name='context';value=([Runtime.Serialization.StreamingContext]::new([Runtime.Serialization.StreamingContextStates]::All))},@{name='entry';value=([Collections.DictionaryEntry]::new('key','value'))},@{name='serializationEntry';value=([Activator]::CreateInstance([Runtime.Serialization.SerializationEntry]))},@{name='tuple';value=([ValueTuple[int,string]]::new(1,'text'))},@{name='member';value=([Reflection.MemberTypes]::Property)},@{name='binding';value=([Reflection.BindingFlags]::Public)},@{name='calling';value=([Reflection.CallingConventions]::Standard)},@{name='methodImpl';value=([Reflection.MethodImplAttributes]::IL)},@{name='genericAttributes';value=([Reflection.GenericParameterAttributes]::Covariant)},@{name='parameterAttributes';value=([Reflection.ParameterAttributes]::Optional)},@{name='contextStates';value=([Runtime.Serialization.StreamingContextStates]::All)},@{name='typeCode';value=([TypeCode]::Int32)},@{name='numberStyle';value=([Globalization.NumberStyles]::Integer)},@{name='timeStyle';value=([Globalization.TimeSpanStyles]::AssumeNegative)},@{name='dateKind';value=([DateTimeKind]::Utc)},@{name='weekday';value=([DayOfWeek]::Monday)},@{name='unnamedNumberStyle';value=([Globalization.NumberStyles]15)},@{name='undefinedTimeStyle';value=([Enum]::ToObject([Globalization.TimeSpanStyles],[int]3))},@{name='intArray';value=([int[]]@(1,2))},@{name='stringArray';value=([string[]]@('text'))},@{name='objectArray';value=([object[]]@('text'))})
$targets=@('System.Object','System.ValueType','System.Enum','System.String','System.Boolean','System.Char','System.SByte','System.Byte','System.Int16','System.UInt16','System.Int32','System.UInt32','System.Int64','System.UInt64','System.Single','System.Double','System.Decimal','System.DateTime','System.TimeSpan','System.Runtime.Serialization.StreamingContext','System.Collections.DictionaryEntry','System.Runtime.Serialization.SerializationEntry','System.Reflection.MemberTypes','System.Reflection.BindingFlags','System.Reflection.CallingConventions','System.Reflection.MethodImplAttributes','System.Reflection.GenericParameterAttributes','System.Reflection.ParameterAttributes','System.Runtime.Serialization.StreamingContextStates','System.TypeCode','System.Globalization.NumberStyles','System.Globalization.TimeSpanStyles','System.DateTimeKind','System.DayOfWeek','System.Int32[]','System.String[]','System.Object[]','System.Void','System.Array')
$rows=@();foreach($sample in $samples){foreach($name in $targets){$type=[Type]::GetType($name,$true);$rows+=[ordered]@{sample=$sample.name;target=$name;result=$type.IsInstanceOfType($sample.value)}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();queries=$rows;qualification='BOUNDED_CORE_BOXED_VALUE_ENUM_AND_ARRAY_INSTANCE_REFERENCE; FULL_BOXING_AND_LANGUAGE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12)+"`n",[Text.UTF8Encoding]::new($false))
Write-Output "PASS pinned boxed value memberships: $($rows.Count) cases"
